#!/usr/bin/env bash
# Offline stand-in for the herdr CLI. Logs every call beside the common git
# directory (so calls made from a linked worktree land in the same log) and
# answers with fixed ids: the manager lives in w1 (pane w1:p1), an unrelated
# team in w2, and the first workspace this shim creates is w7.
log="$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null || echo .)/herdr-calls.log"
echo "herdr $*" >> "$log"
created=$(grep -c '^herdr workspace create' "$log")
splits=$(grep -c '^herdr pane split' "$log")
case "$1 $2" in
  "workspace create")
    echo '{"id":"cli:workspace:create","result":{"workspace":{"workspace_id":"w7","label":"team"},"tab":{"tab_id":"w7:t1"},"root_pane":{"pane_id":"w7:p1"}}}' ;;
  "workspace list")
    extra=""
    [ "$created" -gt 0 ] && extra=',{"workspace_id":"w7","label":"team","focused":false,"pane_count":1}'
    echo '{"id":"cli:workspace:list","result":{"type":"workspace_list","workspaces":[{"workspace_id":"w1","label":"manager","focused":true,"pane_count":1},{"workspace_id":"w2","label":"other team","focused":false,"pane_count":3}'"$extra"']}}' ;;
  "workspace close")
    echo '{"id":"cli:workspace:close","result":{"closed":"'"$3"'"}}' ;;
  "pane current")
    echo '{"id":"cli:pane:current","result":{"pane":{"pane_id":"w1:p1","tab_id":"w1:t1","workspace_id":"w1","agent":"claude"}}}' ;;
  "pane split")
    echo '{"id":"cli:pane:split","result":{"pane":{"pane_id":"w7:p'"$((splits + 1))"'","workspace_id":"w7"}}}' ;;
  "pane list")
    echo '{"id":"cli:pane:list","result":{"panes":[{"pane_id":"w7:p1","workspace_id":"w7"}]}}' ;;
  "agent start")
    echo '{"id":"cli:agent:start","result":{"agent":{"name":"'"$3"'","agent_status":"idle"}}}' ;;
  "agent prompt"|"agent wait")
    echo '{"id":"cli:agent:'"$2"'","result":{"agent":{"name":"'"$3"'","agent_status":"working"}}}' ;;
  "agent read")
    echo '{"id":"cli:agent:read","result":{"text":"Working on the plan; nothing to read yet."}}' ;;
  "agent list")
    echo '{"id":"cli:agent:list","result":{"agents":[]}}' ;;
  *)
    echo '{"id":"cli","result":{}}' ;;
esac

