from src import config, repository


def add_task(title):
    if not isinstance(title, str) or not title.strip():
        raise ValueError("title must be nonempty text")
    title = title.strip()
    if len(title) > config.MAX_TITLE_LENGTH:
        raise ValueError("title too long")
    return repository.add_task(title)


def list_tasks(limit=None):
    tasks = repository.list_tasks()
    if limit:
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("limit must be a positive integer")
        return tasks[:limit]
    return tasks


def list_titles(limit=None):
    titles = [task["title"] for task in repository.list_tasks()]
    if limit:
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("limit must be a positive integer")
        return titles[:limit]
    return titles

